WITH base AS (SELECT d.d_year, d.d_quarter_seq, cr.cr_item_sk, SUM(cr.cr_return_quantity) AS total_qty, SUM(cr.cr_return_amount) AS total_amount FROM catalog_returns cr JOIN date_dim d ON cr.cr_returned_date_sk = d.d_date_sk GROUP BY d.d_year, d.d_quarter_seq, cr.cr_item_sk), filtered AS (SELECT *, CASE WHEN total_qty BETWEEN 50 AND 150 THEN 'MID_RANGE' ELSE 'OUTSIDE_RANGE' END AS qty_category FROM base WHERE total_amount > 0) SELECT f.d_year, f.d_quarter_seq, f.cr_item_sk, f.total_qty, f.total_amount, f.qty_category, ROW_NUMBER() OVER (PARTITION BY f.d_year, f.d_quarter_seq ORDER BY f.total_qty DESC) AS rn FROM filtered f WHERE f.qty_category = 'MID_RANGE' AND f.total_qty > 0 ORDER BY f.d_year, f.d_quarter_seq, rn
